use std :: { fs , thread , path :: PathBuf } ; use glob :: { glob , } ; use rayon :: prelude :: * ; # [cold] pub fn read_unihan_data () -> Vec < Vec < RawEntry > > { let files = glob ("data/unihan/*.txt") . expect ("failed read unihan data files") ; files . into_iter () . filter_map (| x | { if x . is_ok () { Some (to_lines (& x . unwrap ())) } else { None } }) . map (| str | to_rawentries (str)) . collect :: < Vec < Vec < RawEntry > > > () } # [inline (always)] fn to_lines (path : & PathBuf) -> Vec < String > { let s = fs :: read_to_string (path) . expect (format ! ("failed to read {:?}" , & path) . as_str ()) ; s . par_lines () . filter (| str | { str . chars () . nth (0) != Some ('#') }) . map (| str | str . to_string ()) . collect :: < Vec < String > > () } # [inline (always)] fn to_rawentries (lines : Vec < String >) -> Vec < RawEntry > { lines . into_par_iter () . filter_map (| str | { RawEntry :: from_line (str) }) . collect :: < Vec < RawEntry > > () } # [derive (Debug)] pub struct RawEntry { codept : String , char : char , field : String , value : String , } impl RawEntry { # [inline (always)] pub fn from_line (line : String) -> Option < RawEntry > { let v = line . split ('\t') . collect :: < Vec < & str > > () ; (v . len () == 3) . then (| | { let codept = v [0] . to_string () ; let char = { let n = u32 :: from_str_radix (& codept . split ('+') . nth (1) . unwrap () , 16) . unwrap () ; char :: from_u32 (n) . unwrap () } ; let field = v [1] . to_string () ; let value = v [2] . to_string () ; RawEntry { codept , char , field , value } }) } } fn main () { let v = read_unihan_data () ; println ! ("{:#?}" , & v [0] [10 .. 20]) ; }